/**
 * Build the Worker's build-time bundle data: `server/src/meta/bundled-data.ts`.
 *
 * Reads the committed demo store (`server/data/demo/<route>/<key>.json`),
 * the mock fixtures (`server/data/mock/<route>.json`) and the catalog, and
 * writes them as one compact TypeScript module so the Worker serves them
 * from its bundle with no file reads at run time.
 *
 * Node-only (runs at build time via tsx). The generated file is git-ignored
 * and skipped by lint/format; every build and typecheck regenerates it.
 */

/* global console */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { normalizeMockUsage } from "../src/meta/pricing.js";

const here = dirname(fileURLToPath(import.meta.url));
const serverDir = resolve(here, "..");
const repoRoot = resolve(serverDir, "..");
const outFile = join(serverDir, "src", "meta", "bundled-data.ts");

function main(): void {
  const demoDir = join(serverDir, "data", "demo");
  const demoEntries: Array<[string, unknown]> = [];
  for (const route of readdirSync(demoDir).sort()) {
    const dir = join(demoDir, route);
    for (const name of readdirSync(dir)
      .filter((n) => n.endsWith(".json"))
      .sort()) {
      const parsed: unknown = JSON.parse(readFileSync(join(dir, name), "utf8"));
      if (typeof parsed !== "object" || parsed === null) continue;
      const record = parsed as Record<string, unknown>;
      if (typeof record["model"] !== "string") continue;
      const key = name.replace(/\.json$/, "");
      demoEntries.push([`${route}\n${record["model"]}\n${key}`, parsed]);
    }
  }

  const mockDir = join(serverDir, "data", "mock");
  const mockEntries: Array<[string, unknown]> = [];
  for (const name of readdirSync(mockDir)
    .filter((n) => n.endsWith(".json"))
    .sort()) {
    const route = name.replace(/\.json$/, "");
    const parsed: unknown = JSON.parse(readFileSync(join(mockDir, name), "utf8"));
    if (typeof parsed !== "object" || parsed === null) continue;
    const record = parsed as Record<string, unknown>;
    mockEntries.push([
      route,
      {
        data: "data" in record ? record["data"] : parsed,
        usage: normalizeMockUsage(record["usage"]),
      },
    ]);
  }

  const catalog: unknown = JSON.parse(
    readFileSync(join(repoRoot, "shared", "catalog", "catalog.json"), "utf8"),
  );
  const serverPackage: unknown = JSON.parse(readFileSync(join(serverDir, "package.json"), "utf8"));
  const version =
    typeof serverPackage === "object" && serverPackage !== null
      ? String((serverPackage as Record<string, unknown>)["version"] ?? "0.0.0")
      : "0.0.0";

  const out = [
    "/**",
    " * GENERATED by `server/scripts/build-worker-data.ts` — do not edit.",
    " *",
    " * Demo answers, mock fixtures and the catalog bundled into the Worker",
    " * at build time (no file reads at run time). Regenerated on every",
    " * build and typecheck; git-ignored.",
    " */",
    'import type { CatalogItem, DemoStoreFile } from "@fitroom/shared";',
    'import type { TokenUsage } from "./pricing.js";',
    "",
    "export const BUNDLED_DEMO: Array<[string, DemoStoreFile]> = JSON.parse(",
    `  ${JSON.stringify(JSON.stringify(demoEntries))},`,
    ") as Array<[string, DemoStoreFile]>;",
    "",
    "export const BUNDLED_MOCK: Array<[string, { data: unknown; usage: TokenUsage }]> = JSON.parse(",
    `  ${JSON.stringify(JSON.stringify(mockEntries))},`,
    ") as Array<[string, { data: unknown; usage: TokenUsage }]>;",
    "",
    "export const BUNDLED_CATALOG: CatalogItem[] = JSON.parse(",
    `  ${JSON.stringify(JSON.stringify(catalog))},`,
    ") as CatalogItem[];",
    "",
    "export const BUNDLED_VERSION: string = " + `${JSON.stringify(version)};`,
    "",
  ].join("\n");
  writeFileSync(outFile, out, "utf8");
  console.log(
    `build-worker-data: ${String(demoEntries.length)} demo answers, ` +
      `${String(mockEntries.length)} mock fixtures, catalog ` +
      `(${(Buffer.byteLength(out) / 1024).toFixed(0)} KiB) → src/meta/bundled-data.ts`,
  );
}

main();
